class LmdbEarlyLegacyFileTest {
	@Test
	void earlyMutationAndClosePreserveTheLegacyFile(@TempDir(cleanup = CleanupMode.NEVER) Path evidence)
			throws Exception {
		Path legacy = evidence.resolve("join-estimator.rjes");
		byte[] original = { 'R', 'J', 'E', 'S', 1, 7, 0, -1, 2 };
		Files.write(legacy, original, StandardOpenOption.CREATE_NEW);
		AtomicInteger scans = new AtomicInteger();
		try (AutoCloseable preserve = () -> assertArrayEquals(original, Files.readAllBytes(legacy));
				SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator((s, p, o, c) -> {
					scans.incrementAndGet();
					return new CloseableIteratorIteration<>(Collections.emptyIterator());
				}, SketchBasedJoinEstimator.Config.defaults().withMemoryBudgetBytes(4L * 1024L * 1024L))) {
			estimator.registerPersistencePath(legacy);
			assertArrayEquals(original, Files.readAllBytes(legacy));
			assertEquals(0, scans.get(), "registration must not scan the statement source");
			assertFalse(estimator.isReadyNonBlocking(), "registered state remains unavailable until inspected");
			estimator.setRebuildAllowedSupplier(() -> false);
			var vf = SimpleValueFactory.getInstance();
			estimator.addStatement(vf.createStatement(vf.createIRI("urn:early-legacy:s"),
					vf.createIRI("urn:early-legacy:p"), vf.createLiteral(1)));
		}
		assertArrayEquals(original, Files.readAllBytes(legacy));
	}
}
